// Synthetic source for the screen's tests, written into a temporary tree by test/support.ts. Not
// taken from any real application. The planted report drops the currency argument on line 12.

export const CLEAN_REPORT = "// Synthetic source for tests; not taken from any real application.\nimport { formatTotal } from \"./format\";\n\nexport interface ReportFilters {\n  currency?: string;\n  rounding?: number;\n}\n\nexport function buildReport(rows: number[], filters: ReportFilters): string {\n  const { currency = \"usd\", rounding = 2 } = filters;\n  const total = rows.reduce((sum, row) => sum + row, 0);\n  return formatTotal(total, rounding, currency);\n}\n\nexport function buildSummary(rows: number[], filters: ReportFilters): string {\n  const { currency = \"usd\", rounding = 2 } = filters;\n  const average = rows.length === 0 ? 0 : rows.reduce((sum, row) => sum + row, 0) / rows.length;\n  return formatTotal(average, rounding, currency);\n}\n";

export const PLANTED_REPORT = "// Synthetic source for tests; not taken from any real application.\nimport { formatTotal } from \"./format\";\n\nexport interface ReportFilters {\n  currency?: string;\n  rounding?: number;\n}\n\nexport function buildReport(rows: number[], filters: ReportFilters): string {\n  const { currency = \"usd\", rounding = 2 } = filters;\n  const total = rows.reduce((sum, row) => sum + row, 0);\n  return formatTotal(total, rounding);\n}\n\nexport function buildSummary(rows: number[], filters: ReportFilters): string {\n  const { currency = \"usd\", rounding = 2 } = filters;\n  const average = rows.length === 0 ? 0 : rows.reduce((sum, row) => sum + row, 0) / rows.length;\n  return formatTotal(average, rounding, currency);\n}\n";

export const FORMAT = "// Synthetic source for tests; not taken from any real application.\nconst SYMBOLS: Record<string, string> = { usd: \"$\", eur: \"€\", jpy: \"¥\" };\n\nexport function formatTotal(value: number, rounding: number, currency = \"usd\"): string {\n  const symbol = SYMBOLS[currency] ?? \"\";\n  return `${symbol}${value.toFixed(rounding)}`;\n}\n";
